const $=id=>document.getElementById(id);let leads=[];
$('search').onclick=async()=>{let place=$('place').value.trim(),kind=$('kind').value.trim();if(!place||!kind){$('status').textContent='Enter a location and business type.';return}let box=$('cards');box.replaceChildren();$('status').textContent='Searching…';try{let geo=await(await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(place))).json();if(!geo.length)throw Error('Location not found');let b=geo[0].boundingbox,k=kind.replace(/[^a-z0-9 ]/gi,'').trim().split(/\s+/).join('|'),q=`[out:json][timeout:25];(nwr["name"]["shop"~"${k}"](${b[0]},${b[2]},${b[1]},${b[3]});nwr["name"]["amenity"~"${k}"](${b[0]},${b[2]},${b[1]},${b[3]}););out center 50;`;let data=await(await fetch('https://overpass-api.de/api/interpreter?data='+encodeURIComponent(q))).json();leads=data.elements.map(e=>({name:e.tags.name,website:e.tags.website||e.tags['contact:website'],address:[e.tags['addr:housenumber'],e.tags['addr:street']].filter(Boolean).join(' ')})).sort((a,b)=>!!a.website-!!b.website);$('status').textContent=`${leads.length} listings found. “No website listed” does not prove a site is absent.`;leads.forEach((lead,i)=>{let card=document.createElement('article');card.className='card';let title=document.createElement('h3');title.textContent=lead.name;let status=document.createElement('p');status.textContent=lead.website?'Website listed — review its quality':'No website listed — verify';let addr=document.createElement('p');addr.textContent=lead.address;let link=document.createElement('a');link.href=lead.website?(/^https?:\/\//i.test(lead.website)?lead.website:'https://'+lead.website):'https://www.google.com/search?q='+encodeURIComponent(lead.name+' '+place+' website');link.target='_blank';link.rel='noopener';link.textContent=lead.website?'Visit website':'Check for a website';let button=document.createElement('button');button.textContent='Draft email';button.onclick=()=>draft(i);card.append(title,status,addr,link,document.createElement('br'),button);box.append(card)})}catch(e){$('status').textContent='Search unavailable: '+e.message+'. Try another area or again later.'}};
function draft(i){let lead=leads[i],sender=$('sender').value.trim()||'[your business]';$('email').value=`Subject: A website idea for ${lead.name}\n\nHi ${lead.name} team,\n\nI came across your business while looking at local ${$('kind').value.trim()} businesses. [Add a genuine detail you noticed about the business or website.]\n\nI'm with ${sender}. We create clear, mobile-friendly websites that help local customers find what they need and get in touch. I'd love to share a few ideas tailored to ${lead.name}.\n\nWould you be open to a brief conversation next week?\n\nBest,\n[Your name]\n${sender}`;$('email').scrollIntoView({behavior:'smooth'})}
$('copy').onclick=async()=>{await navigator.clipboard.writeText($('email').value);$('copy').textContent='Copied!';setTimeout(()=>$('copy').textContent='Copy email',1500)};
